function poisonBite(target){if(target.monster==='mechanicus'){message('Mechanicus is immune to poison.');return;}target.poisoned=true;target.poisonSource={playerId:state.id||null,human:!state.aiRival&&(!state.players||state.players.some(p=>p.id===state.id)),player:state.playerName||'Player',monster:state.monster};message(monsterName(target.monster)+' is poisoned: −1 health each turn.');}
