function poisonTurn(){tickPoison(state);for(const enemy of state.enemies.filter(e=>e.type==='kaiju'))if(tickPoison(enemy)){if(enemy.poisonSource?.human){awardDefeat(enemy);state.kills++;}state.enemies=state.enemies.filter(e=>e!==enemy);}cap();}


