function youngFeed(cityDamage=true){if(concealed())return false;const targets=feedTargets(),selected=selectedTarget();let target=targets.find(e=>e===selected||e.type==='civilian'&&selected?.type==='civilian')||targets.sort(youngPriority)[0];if(!target)return false;const bites=state.abilities.includes('Double feeding')?2:1;for(let n=0;n<bites;n++){if(!target||target.hp<=0)target=feedTargets().sort(youngPriority)[0];if(!target)break;let eaten=false;if(target.type==='civilian'){state.food[state.pos]--;target.hp=0;awardDefeat(target);eaten=true;}else{damageTarget(target,3);if(target.hp<=0){recordCoachMeal(target);awardDefeat(target);state.enemies=state.enemies.filter(e=>e!==target);state.kills++;eaten=true;}}state.en+=state.abilities.includes('Feeding frenzy')?7:5;if(eaten&&cityDamage)damageDistrict(10);message('Youngson bites '+unitName(target)+' for 3 damage and restores energy.');}cap();return true;}
