function autoFeed(){if(isMartian())martianSweep();if(isChing())chingClaw();if(isBalrog()&&state.damage[state.pos]<100){state.fire[state.pos]=true;message('Balrog sets '+districts[state.pos].name+' on fire.');}if(isBlob()&&feedTargets().length)feedAttack(false)}
function specialSectors(){if(isChing())return chingSectors();return isHydra()||state.abilities.includes('Extended range')?[state.pos,...districts[state.pos].links]:[state.pos]}
function hit(special,requested){if(isHydra()&&!special)return false;if(!special&&holding())return false;if(concealed())return false;if(isYoungson()&&special)return youngHit(requested);if(isGroot()&&special)return grootHit(requested);if(isMartian())return martianHit(special,requested);if(isChing())return chingHit(special,requested);if(isHydra())return hydraHit(special,requested);if(isArachnoid())return arachnoidHit(special,requested);if(isBalrog()||(isMechanicus()&&special))return balrogHit(special,requested);const sector=special?(requested??Number($('specialTarget').value||state.pos)):state.pos;if(special&&!specialSectors().includes(sector))return false;const units=state.enemies.filter(e=>e.pos===sector&&!isHiddenTarget(e));const targets=special?(isBlob()?units.slice(0,Math.max(0,splatCount()-Math.min(state.food[sector],splatCount()))):units):units.filter(clawTarget).sort((a,b)=>Number(b===selectedTarget())-Number(a===selectedTarget())||a.hp-b.hp).slice(0,1);const civilians=special?(isBlob()?Math.min(state.food[sector],splatCount()):state.food[sector]):0;if(!special&&!targets.length)return false;const damage=special?3:2+(state.abilities.includes('Razor claws')?1:0);if(special){if(state.en<specialEnergyCost(2))return false;state.en-=specialEnergyCost(2);damageDistrict(isBlob()?splatCount()*10:30,sector);state.fire[sector]=state.damage[sector]<100;message(districts[sector].name+(state.fire[sector]?' catches fire from the special attack.':' is rubble and cannot burn.'));state.food[sector]-=civilians;awardDefeat({type:'civilian'},civilians);if(civilians)message('Special attack deals 3 damage to all '+civilians+' one-health civilians in '+districts[sector].name+'.');}if(!special)damageDistrict(10,sector);for(const enemy of targets){const dealt=special&&isBlob()?enemy.hp:damage;damageTarget(enemy,dealt);message((special?(isBlob()?'Splat Attack':'Atomic roar'):'Claw attack')+' hits '+unitName(enemy)+' for '+dealt+'.');if(enemy.hp<=0)defeat(enemy);}cap();return true}
function balrogHit(special,requested){const sector=special?(requested??state.pos):state.pos;if(special&&(!specialSectors().includes(sector)||state.en<specialEnergyCost(2)))return false;const eligible=()=>state.enemies.filter(e=>e.pos===sector&&(special||clawTarget(e)));if(!special&&!eligible().length&&!state.food[sector])return false;if(special){state.en-=specialEnergyCost(2);damageDistrict(30,sector);if(!isMechanicus())state.fire[sector]=state.damage[sector]<100;}else damageDistrict(10,sector);for(let n=0;n<strikeCount();n++){const units=eligible();const scientist=units.find(e=>e.type==='scientist'),rival=units.find(e=>e.type==='kaiju'),air=units.find(e=>e.unit==='helicopter');let target=scientist||rival||air;if(!target){const ground=[...units,...Array.from({length:state.food[sector]},()=>({type:'civilian',hp:1,pos:sector}))];if(!ground.length)break;target=ground[Math.floor(Math.random()*ground.length)];}const damage=special?3:2+(state.abilities.includes('Razor claws')?1:0);if(target.type==='civilian'){state.food[sector]--;awardDefeat(target);}else{damageTarget(target,damage);if(target.hp<=0)defeat(target);}message((special?(isMechanicus()?'Death Ray':'Flaming Whip'):'Claw attack')+' strike '+(n+1)+' hits '+(target.unit||target.type)+' for '+damage+'.');}cap();return true}
function walkingDamage(){if(isMartian()&&state.flying)return;if(isArachnoid()){state.flying??=false;state.webs??=Array(districts.length).fill(0);state.webs[state.pos]=10;message('Arachnoid lays a web: 10 HP in '+districts[state.pos].name+'.');}else damageDistrict(10)}
