function damageWeb(i,amount){if((state.webs?.[i]||0)>0){state.webs[i]=Math.max(0,state.webs[i]-amount);message('Web in '+districts[i].name+' takes '+amount+' damage: '+state.webs[i]+' HP remain.');}}
function webStops(e,to=e.pos){if(e.monster==='martians'&&e.flying)return false;if((e.flameUntil||0)>state.turn||(state.flameWebs?.[e.pos]||0)>state.turn||(state.flameWebs?.[to]||0)>state.turn)return true;if(airborne(e)||e.type==='kaiju')return false;const at=webActive(e.pos)?e.pos:webActive(to)?to:-1;if(at<0)return false;if(e.type==='coach')return true;damageWeb(at,e.type==='police'?1:e.unit==='tank'?3:2);return true}
function arachnoidHit(special,requested){const sector=special?(requested??state.pos):state.pos;if(special&&(!specialSectors().includes(sector)||state.en<specialEnergyCost(2)))return false;const count=special?flameLevel():state.abilities.includes('Double Claw')?2:1;if(!special&&!state.food[sector]&&!state.enemies.some(e=>e.pos===sector&&clawTarget(e)))return false;if(special){state.en-=specialEnergyCost(2);damageDistrict(30,sector);state.fire[sector]=state.damage[sector]<100;state.flameWebs??=Array(districts.length).fill(0);state.flameWebs[sector]=state.turn+1;}else damageDistrict(10,sector);const struck=new Set();for(let n=0;n<count;n++){const units=state.enemies.filter(e=>e.pos===sector&&!struck.has(e)&&(special||clawTarget(e)));let target=special?(units.find(e=>e.type==='scientist')||units.find(e=>e.type==='kaiju')||units.find(airborne)):units.find(e=>e===selectedTarget());if(!target){const ground=[...units,...Array.from({length:state.food[sector]},()=>({type:'civilian',hp:1,pos:sector}))];if(!ground.length)break;target=ground[Math.floor(Math.random()*ground.length)];}if(target.type==='civilian'){state.food[sector]--;awardDefeat(target);}else{struck.add(target);if(special)target.flameUntil=state.turn+1;if(special)damageTarget(target,3);else if(target.type==='kaiju')damageTarget(target,2+(state.abilities.includes('Razor claws')?1:0));else target.hp=0;if(target.hp<=0)defeat(target);}message((special?'Flaming Web Shooter hits':'Spider claw defeats')+' '+(target.unit||target.type)+'.');}cap();return true}
function hydraHit(special,requested){if(!special)return false;if(concealed())return false;const sector=special?(requested??state.pos):state.pos;if(special&&(!specialSectors().includes(sector)||state.en<specialEnergyCost(1)))return false;let remaining=special&&!state.megaResolving?Math.min(hydraHeads(),Math.floor(state.en)*3):hydraHeads(),used=0;const choose=()=>{const units=state.enemies.filter(e=>e.pos===sector&&!isHiddenTarget(e)&&(special||clawTarget(e)));const scientist=units.find(e=>e.type==='scientist'),air=units.find(airborne),rival=units.find(e=>e.type==='kaiju');if(scientist||air||rival)return scientist||air||rival;const ground=[...units,...Array.from({length:state.food[sector]},()=>({type:'civilian',hp:1,pos:sector}))];return ground.length?ground[Math.floor(Math.random()*ground.length)]:null;};let target=choose();while(remaining>0&&target){used++;remaining--;if(target.type==='civilian'){state.food[sector]--;awardDefeat(target);target=choose();}else{damageTarget(target,1);if(target.hp<=0){defeat(target);target=choose();}}}if(!used)return false;if(special){const cost=specialEnergyCost(Math.ceil(used/3));state.en-=cost;damageDistrict(30,sector);state.fire[sector]=state.damage[sector]<100;message('Lightning: '+used+' head attacks, 1 damage each. −'+cost+' energy.');}else{damageDistrict(10,sector);message('Hydra claws: '+used+' head attacks, 1 damage each.');}cap();return true}
function damageTarget(enemy,damage){if(isHiddenTarget(enemy))return;const actual=Math.max(0,damage-armorReduction(enemy.abilities||[],enemy.monster));enemy.hp=roundStat(Math.max(0,enemy.hp-actual));}
