function evolve(ability){if(motionBusy)return;if(!availableEvolutions().includes(ability)||state.hp!==healthMax()||state.en!==energyMax()||state.evolved||state.abilities.includes(ability))return;state.abilities.push(ability);if(ability==='Third action')state.actionsLeft++;state.evolved=true;message(ability.startsWith('Vitality ')?'EVOLUTION: +1 Energy / Health. Both bars gain one empty segment.':'EVOLUTION: '+ability+' acquired.');render()}
