function selectDistrict(i){if(aiming){if(!canAim()||!specialSectors().includes(i))return;aiming=false;act('special',i);}else if(i!==state.pos)act('move',i)}

function copyState(){return JSON.parse(JSON.stringify(state))}
function recordMove(type,from,to,count=1){if(isGroot()&&['monster','rival:grootius'].includes(type)&&from>=0&&to>=0&&from!==to)plantBaby(from);if(buildingMotion&&from!==to)motionMoves.push({type,from,to,count})}
