function act(kind,arg){runAction(()=>performAction(kind,arg))}
function berserk(){runAction(performBerserk)}
function runAction(fn){if(motionBusy)return;unlockAudio();buildingMotion=true;motionFrames=[];motionMoves=[];actionStart=copyState();try{fn()}finally{buildingMotion=false;actionStart=null}if(typeof requestAnimationFrame==='function'&&motionFrames.some(f=>f.moves.length||f.sounds?.length))playFrames(motionFrames,copyState());else render();}
