async function playFrames(frames,finalState){motionBusy=true;aiming=false;const show=(snapshot,label,moves)=>{const authoritative=state;state=snapshot;activeMotions=moves;render();state=authoritative;$('movementPhase').textContent=label+' · moving for 2 seconds';$('movementPhase').hidden=false;$('restart').disabled=true;};try{for(const frame of frames){if(!frame.moves.length&&!frame.sounds?.length)continue;show(frame.after,frame.label,frame.moves);for(const type of new Set([...frame.moves.map(m=>m.type),...(frame.sounds||[])]))playSound(type);await new Promise(resolve=>setTimeout(resolve,2000));}}finally{activeMotions=[];state=finalState;motionBusy=false;$('movementPhase').hidden=true;$('restart').disabled=false;render();}}
